    </footer>
    <script>
    // FAQ: the questions are written in the page; the JavaScript only does the search.
    (() => {
        const list = document.getElementById('faq-list');
        const input = document.getElementById('faq-search');
        const empty = document.getElementById('faq-empty');
        if (!list) return;
        const norm = s => String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        const cats = [...list.querySelectorAll('.presentation-faq-cat')].map(box => ({
            box,
            rows: [...box.querySelectorAll('.presentation-faq-item')].map(d => ({ d, text: norm(d.textContent) })),
        }));
        input.addEventListener('input', () => {
            const words = norm(input.value).split(/\s+/).filter(Boolean);
            let total = 0;
            cats.forEach(({ box, rows }) => {
                let shown = 0;
                rows.forEach(({ d, text }) => {
                    const ok = words.every(w => text.includes(w));
                    d.hidden = !ok;
                    d.open = ok && words.length > 0;
                    if (ok) shown++;
                });
                box.hidden = shown === 0;
                total += shown;
            });
            empty.hidden = total > 0;
        });
    })();
    </script>
    <script>
    // Preview carousel: it never scrolls by itself (arrows, dots, keyboard, swipe).
    (() => {
        const track = document.querySelector('.presentation-carousel-track');
        if (!track) return;
        const slides = [...track.querySelectorAll('.presentation-slide')];
        const prev = document.querySelector('[data-carousel-prev]');
        const next = document.querySelector('[data-carousel-next]');
        const dotsBox = document.querySelector('.presentation-carousel-dots');
        const dots = slides.map((_, i) => {
            const dot = document.createElement('button');
            dot.type = 'button';
            dot.setAttribute('aria-label', 'Image ' + (i + 1));
            dot.addEventListener('click', () => go(i));
            dotsBox.appendChild(dot);
            return dot;
        });
        const current = () => Math.round(track.scrollLeft / track.clientWidth);
        const go = (i) => track.scrollTo({ left: Math.max(0, Math.min(slides.length - 1, i)) * track.clientWidth });
        const refresh = () => {
            const i = current();
            dots.forEach((dot, k) => dot.setAttribute('aria-current', k === i ? 'true' : 'false'));
            prev.disabled = i <= 0;
            next.disabled = i >= slides.length - 1;
        };
        prev.addEventListener('click', () => go(current() - 1));
        next.addEventListener('click', () => go(current() + 1));
        track.addEventListener('keydown', (e) => {
            if (e.key === 'ArrowLeft') { e.preventDefault(); go(current() - 1); }
            if (e.key === 'ArrowRight') { e.preventDefault(); go(current() + 1); }
        });
        track.addEventListener('scroll', () => window.requestAnimationFrame(refresh), { passive: true });
        window.addEventListener('resize', refresh);
        refresh();
    })();
    </script>
    <script>
    // Direct links (#v0-10-0, #faq-3, #q-3-12): the target block and the ones around it open, on load and on click.
    (() => {
        const openTo = (hash, scroll) => {
            let el = null;
            try { el = hash && hash.length > 1 ? document.querySelector(hash) : null; } catch (_) { return; }
            if (!el) return;
            for (let p = el; p; p = p.parentElement) if (p.tagName === 'DETAILS') p.open = true;
            if (scroll) el.scrollIntoView({ block: 'start' });
        };
        document.addEventListener('click', e => {
            const a = e.target.closest('a[href^="#"]');
            if (a) openTo(a.getAttribute('href'), false);
        });
        window.addEventListener('hashchange', () => openTo(location.hash, true));
        if (location.hash) openTo(location.hash, true);
    })();
    </script>
